{
  "name": "ChaosPilot Trading Gateway",
  "description": "Deterministic single-account trading gateway with credit reservation, quote locking, and venue execution reconciliation. Fresh instances begin with no orders, no active quote, and no credit limit. Quotes lock execution prices for subsequent orders; orders reserve quantity * locked price against active credit limit. Valid execution reports convert reserved credit to used credit. Confirmed cancellations release only explicitly cancelled quantity. Status is FILLED when filledQuantity equals initialQuantity, otherwise CANCELLED for positive confirmed cancelledQuantity, otherwise OPEN. remainingQuantity is unreconciled quantity (including earlier execution reports still in transit), not executable leaves after cancellation; cancellationRequested is diagnostic only. A zero cancellation never relabels a fully filled order. Cancellation cannot predate an already accepted execution. Valid business facts occurring before or at cancellation remain binding even if delivered out of order. Coherent fabricated reports on the reports channel adhere to identical public consistency rules as venue-generated reports. Identical business facts are processed idempotently; conflicting duplicate IDs or inconsistent quantities/prices/business timestamps are rejected with zero mutation.",
  "operations": [
    {
      "op": "send",
      "description": "Schedules a message to a channel for future delivery. Permits fabricated reports subject to public business consistency rules.",
      "parameters": {
        "id": "Unique envelope identifier string",
        "to": "Destination channel: market, credit, client, or reports",
        "payload": "Message payload object",
        "delay": "Optional tick delay before delivery eligibility (default: 0)"
      }
    },
    {
      "op": "duplicate",
      "description": "Creates a duplicate envelope of an existing message with a new transport ID.",
      "parameters": {
        "messageId": "Identifier of existing envelope to duplicate",
        "id": "New unique envelope identifier string",
        "delay": "Optional tick delay before delivery eligibility (default: 0)"
      }
    },
    {
      "op": "deliver",
      "description": "Delivers a specific scheduled message to the target gateway if due time has arrived.",
      "parameters": {
        "messageId": "Identifier of due envelope to deliver"
      }
    },
    {
      "op": "advance",
      "description": "Advances simulation logical time by a number of ticks.",
      "parameters": {
        "ticks": "Positive integer number of ticks to advance"
      }
    },
    {
      "op": "drain",
      "description": "Sequentially delivers all pending envelopes ordered by due time then insertion sequence, advancing logical time."
    },
    {
      "op": "fill",
      "identity": "Reusing an orderId/executionId with identical quantity reissues the original fact and occurrence time; conflicting quantities are rejected.",
